parameters.query:
SELECT source, last_run_at, last_success_at, last_error, jobs_seen_total
  FROM sources_health
 ORDER BY last_run_at DESC NULLS LAST;

parameters.jsCode:
const metrics = $('Postgres: métricas D-1').all().map(i => i.json);
const top = $('Postgres: top 5 matches').all().map(i => i.json);
const gaps = $('Postgres: top gaps semana').all().map(i => i.json);
const health = $('Postgres: sources_health').all().map(i => i.json);

const today = new Date().toISOString().slice(0,10);
const seen = metrics.reduce((s,m) => s + Number(m.jobs_seen ?? 0), 0);
const matched = metrics.reduce((s,m) => s + Number(m.jobs_matched ?? 0), 0);
const sent = metrics.reduce((s,m) => s + Number(m.applications_sent ?? 0), 0);

let html = `<h1>Relatório diário — ${today}</h1>`;
html += `<h2>KPIs (últimas 24h)</h2><ul>`;
html += `<li><strong>Vagas vistas:</strong> ${seen}</li>`;
html += `<li><strong>Com match ≥70:</strong> ${matched}</li>`;
html += `<li><strong>Candidaturas enviadas:</strong> ${sent}</li></ul>`;

html += `<h2>Por plataforma</h2><table border="1" cellpadding="6" cellspacing="0"><tr><th>Fonte</th><th>Vistas</th><th>Match</th><th>Enviadas</th></tr>`;
for (const m of metrics) html += `<tr><td>${m.source}</td><td>${m.jobs_seen}</td><td>${m.jobs_matched}</td><td>${m.applications_sent}</td></tr>`;
html += `</table>`;

html += `<h2>Top 5 vagas do dia</h2>`;
for (const t of top) html += `<p><strong>${t.score}</strong> — <a href="${t.url}">${t.title} @ ${t.company}</a> (${t.location})<br><em>${t.summary || ''}</em></p>`;

html += `<h2>Top skills em gap (7 dias)</h2><ul>`;
for (const g of gaps) html += `<li><strong>${g.skill}</strong> — ${g.n} vagas</li>`;
html += `</ul>`;

html += `<h2>Saúde dos conectores</h2><table border="1" cellpadding="6" cellspacing="0"><tr><th>Fonte</th><th>Última coleta</th><th>Erro</th><th>Total vistas</th></tr>`;
for (const h of health) html += `<tr><td>${h.source}</td><td>${h.last_run_at || '-'}</td><td>${h.last_error || '✓'}</td><td>${h.jobs_seen_total}</td></tr>`;
html += `</table>`;

return [{ json: {
  date: today,
  subject: `📊 AUTOMA-O — Relatório ${today} (vistas: ${seen}, match: ${matched}, enviadas: ${sent})`,
  html,
  to: ($env && $env.NOTIFY_EMAIL_TO) || 'fabiokansas@gmail.com',
  driveContent: html
}}];
